import{_t as e,it as t,n,rt as r}from"./chunks/framework.wyZghjns.js";var i=JSON.parse(`{"title":"Enumeration: BitFlags","description":"","frontmatter":{},"headers":[],"relativePath":"api/@jsprismarine/raknet/enumerations/BitFlags.md","filePath":"api/@jsprismarine/raknet/enumerations/BitFlags.md"}`),a={name:`api/@jsprismarine/raknet/enumerations/BitFlags.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><a href="./../../../">JSPrismarine</a> / <a href="./../">@jsprismarine/raknet</a> / BitFlags</p><h1 id="enumeration-bitflags" tabindex="-1">Enumeration: BitFlags <a class="header-anchor" href="#enumeration-bitflags" aria-label="Permalink to “Enumeration: BitFlags”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ca2affbec3a61b1177fd73fcd46aecb6c154be1c/packages/raknet/src/protocol/BitFlags.ts#L14" target="_blank" rel="noreferrer">packages/raknet/src/protocol/BitFlags.ts:14</a></p><p>The bits of a datagram&#39;s first byte, and the split bit of a frame&#39;s.</p><p><code>VALID</code> marks a datagram of the reliability layer at all; <code>ACK</code> and <code>NACK</code> say which kind it is, and a datagram with neither carries frames. The low bits of a data datagram are hints for RakNet&#39;s congestion control: <code>PACKET_PAIR</code>, <code>CONTINUOUS_SEND</code> and <code>NEEDS_B_AND_AS</code>. The sliding window variant Bedrock uses ignores all three on receipt, so a client datagram tagged <code>0x84</code> or <code>0x8c</code> decodes exactly like the <code>0x80</code> we send.</p><p><code>SPLIT</code> lives in a frame header byte, not the datagram&#39;s, and happens to share its value with the packet pair bit; it is listed here because the frame codec always has.</p><h2 id="see" tabindex="-1">See <a class="header-anchor" href="#see" aria-label="Permalink to “See”">​</a></h2><p><a href="https://github.com/facebookarchive/RakNet/blob/master/Source/ReliabilityLayer.cpp#L150" target="_blank" rel="noreferrer">https://github.com/facebookarchive/RakNet/blob/master/Source/ReliabilityLayer.cpp#L150</a></p><h2 id="enumeration-members" tabindex="-1">Enumeration Members <a class="header-anchor" href="#enumeration-members" aria-label="Permalink to “Enumeration Members”">​</a></h2><h3 id="ack" tabindex="-1">ACK <a class="header-anchor" href="#ack" aria-label="Permalink to “ACK”">​</a></h3><blockquote><p><strong>ACK</strong>: <code>64</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ca2affbec3a61b1177fd73fcd46aecb6c154be1c/packages/raknet/src/protocol/BitFlags.ts#L16" target="_blank" rel="noreferrer">packages/raknet/src/protocol/BitFlags.ts:16</a></p><hr><h3 id="continuous-send" tabindex="-1">CONTINUOUS_SEND <a class="header-anchor" href="#continuous-send" aria-label="Permalink to “CONTINUOUS_SEND”">​</a></h3><blockquote><p><strong>CONTINUOUS_SEND</strong>: <code>8</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ca2affbec3a61b1177fd73fcd46aecb6c154be1c/packages/raknet/src/protocol/BitFlags.ts#L21" target="_blank" rel="noreferrer">packages/raknet/src/protocol/BitFlags.ts:21</a></p><p>The sender had more queued behind this datagram.</p><hr><h3 id="nack" tabindex="-1">NACK <a class="header-anchor" href="#nack" aria-label="Permalink to “NACK”">​</a></h3><blockquote><p><strong>NACK</strong>: <code>32</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ca2affbec3a61b1177fd73fcd46aecb6c154be1c/packages/raknet/src/protocol/BitFlags.ts#L17" target="_blank" rel="noreferrer">packages/raknet/src/protocol/BitFlags.ts:17</a></p><hr><h3 id="needs-b-and-as" tabindex="-1">NEEDS_B_AND_AS <a class="header-anchor" href="#needs-b-and-as" aria-label="Permalink to “NEEDS_B_AND_AS”">​</a></h3><blockquote><p><strong>NEEDS_B_AND_AS</strong>: <code>4</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ca2affbec3a61b1177fd73fcd46aecb6c154be1c/packages/raknet/src/protocol/BitFlags.ts#L23" target="_blank" rel="noreferrer">packages/raknet/src/protocol/BitFlags.ts:23</a></p><p>The sender is in slow start and would like bandwidth estimates in our acknowledgments.</p><hr><h3 id="split" tabindex="-1">SPLIT <a class="header-anchor" href="#split" aria-label="Permalink to “SPLIT”">​</a></h3><blockquote><p><strong>SPLIT</strong>: <code>16</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ca2affbec3a61b1177fd73fcd46aecb6c154be1c/packages/raknet/src/protocol/BitFlags.ts#L19" target="_blank" rel="noreferrer">packages/raknet/src/protocol/BitFlags.ts:19</a></p><p>On a datagram: the second of a packet pair. On a frame: one fragment of a split message.</p><hr><h3 id="valid" tabindex="-1">VALID <a class="header-anchor" href="#valid" aria-label="Permalink to “VALID”">​</a></h3><blockquote><p><strong>VALID</strong>: <code>128</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ca2affbec3a61b1177fd73fcd46aecb6c154be1c/packages/raknet/src/protocol/BitFlags.ts#L15" target="_blank" rel="noreferrer">packages/raknet/src/protocol/BitFlags.ts:15</a></p>`,35)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};